@startuml

class Researcher {
  + name : string
  + surname : string
  + researchGroup : ResearchGroup
}

class ResearchGroup {
  + name : string
  + department : Department
  + leader : Researcher
}

class Department {
  + name : string
}

class WorkPackage {
  + id : int
  + title : string
  + leader : ResearchGroup
  + researchers : Researcher[]
}

Researcher "1" -- "0..*" WorkPackage : assigned to

Researcher "1" -- "1" ResearchGroup : belongs to

ResearchGroup "1" *-- "1..*" WorkPackage : leads

Department "1" *-- "1..*" ResearchGroup : contains

WorkPackage "1" -- "0..*" Researcher : includes

@enduml

